+  let (message, omitted) = match error {
+    AdapterError(detail) => (detail, false)
+    InvalidConfig(detail) => (detail, false)
+    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
+    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
+    @json.InvalidNumber(position, _) =>
