117	async fn diagnostic_recording_warning(
118	  reason : String,
119	  phase~ : String = "",
120	  os_errno? : Int32,
121	) -> Unit {
122	  if reason == "workspace_recording_unknown" {
123	    diagnostic_recording_health.run_partial = true
124	  }
125	  let publish = !diagnostic_recording_health.incident ||
126	    diagnostic_recording_health.reason != reason ||
127	    diagnostic_recording_health.phase != phase
128	  diagnostic_recording_health.incident = true
129	  diagnostic_recording_health.incident_serial += 1
130	  if diagnostic_recording_health.dropped == 0 {
131	    diagnostic_recording_health.reason = reason
132	    diagnostic_recording_health.phase = phase
133	    diagnostic_recording_health.os_errno = os_errno
134	  }
135	  if publish {
136	    publish_diagnostic_health()
137	  }
138	  if !diagnostic_recording_health.warned {
139	    diagnostic_recording_health.warned = true
140	    @async.with_timeout(10, async fn() {
141	      @stdio.stderr.write(
142	        "orca-env-devsy: warning: diagnostic recording is unavailable (" +
143	        reason +
144	        (if phase == "" { "" } else { ", phase=" + phase }) +
145	        os_errno.map(code => ", errno=" + code.to_string()).unwrap_or("") +
146	        ")\n",
147	      )
148	    }) catch {
149	      _ => ()
150	    }
151	  }
152	}
