156	  reason : String,
157	  phase~ : String = "",
158	  os_errno? : Int32,
159	  event_time? : UInt64,
160	) -> Unit {
161	  let time = event_time.unwrap_or(@env.now())
162	  let health_changed = diagnostic_recording_health.reason != reason ||
163	    diagnostic_recording_health.phase != phase
164	  if diagnostic_recording_health.dropped == 0 {
165	    diagnostic_recording_health.first_dropped = time
166	    diagnostic_recording_health.last_dropped = time
167	  } else {
168	    if time < diagnostic_recording_health.first_dropped {
169	      diagnostic_recording_health.first_dropped = time
170	    }
171	    if time > diagnostic_recording_health.last_dropped {
172	      diagnostic_recording_health.last_dropped = time
173	    }
174	  }
175	  diagnostic_recording_health.dropped += 1
176	  diagnostic_recording_health.run_partial = true
177	  diagnostic_recording_health.reason = reason
178	  diagnostic_recording_health.phase = phase
179	  diagnostic_recording_health.os_errno = os_errno
180	  diagnostic_recording_warning(reason, phase~, os_errno?)
181	  if health_changed {
182	    publish_diagnostic_health()
183	  }
184	}
