256	///|
257	async fn recover_diagnostic_health(directory : String) -> Unit {
258	  if @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") == Some("0") {
259	    return
260	  }
261	  let path = directory + "/diagnostic-health.json"
262	  if !@fs.exists(path) {
263	    return
264	  }
265	  let previous = @async.with_timeout(20, async fn() {
266	    guard @fs.kind(path, follow_symlink=false) == @fs.FileKind::Regular &&
267	      @fs.file_size(path) <= 65536L else {
268	      return Json::null()
269	    }
270	    @json.parse(@fs.read_file(path).text())
271	  }) catch {
272	    error =>
273	      if @async.is_being_cancelled() {
274	        raise error
275	      } else {
276	        Json::null()
277	      }
278	  }
279	  if field(previous, "priorLoss") is Some(Json::Array(losses)) {
280	    for loss in losses {
281	      if diagnostic_previous_losses.length() >= 31 {
282	        break
283	      }
284	      diagnostic_previous_losses.push(diagnostic_previous_loss(loss))
285	    }
286	    if losses.length() > 31 {
287	      diagnostic_previous_losses.push(diagnostic_previous_loss(Json::null()))
288	    }
289	  }
290	  diagnostic_previous_losses.push(diagnostic_previous_loss(previous))
291	  for event in diagnostic_previous_losses {
292	    diagnostic_pending.push({ event, failed: true, time: @env.now(), })
293	  }
294	  diagnostic_recording_health.incident = true
295	  diagnostic_recording_health.reason = "previous_run_unflushed"
296	  diagnostic_recording_health.phase = "recovery"
297	}
