502	async fn save_diagnostic(
503	  stage : String,
504	  status : String,
505	  exit_code? : Int32,
506	  error_type? : String,
507	  phase? : String,
508	  duration_ms? : Double,
509	  attempt? : Int32,
510	  retry_delay_ms? : Int32,
511	  timeout_ms? : Int32,
512	  os_errno? : Int32,
513	  source? : CreateEvidence,
514	  error_message? : String,
515	  details_truncated~ : Bool = false,
516	  tunnel_directory? : String,
517	  expected_workspace_uid? : String,
518	  observed_workspace_uid? : String,
519	  evidence? : Json,
520	  evidence_incomplete~ : Bool = false,
521	  evidence_stable_activity~ : Bool = false,
522	  evidence_stable_operation~ : Bool = false,
523	  run_completeness? : String,
524	  recording? : Bool,
525	  environment? : Map[String, String],
526	  protected_secrets? : Array[String],
527	) -> Unit {
528	  if !recording.unwrap_or(
529	      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
530	    ) {
531	    return
532	  }
533	  diagnostic_run_has_events.val = true
534	  let event_time = @env.now()
535	  let event : Json = {
536	    "stage": stage,
537	    "status": status,
538	    "time": event_time.to_string(),
539	    "runId": recording_run_id,
540	    "adapterVersion": version,
541	  }
542	  if create_recording.attempt > 0 {
543	    set_field(
544	      event,
545	      "createAttempt",
546	      Json::number(create_recording.attempt.to_double()),
547	    )
548	    set_field(event, "createPhase", Json::string(create_recording.phase))
549	  }
550	  let process_environment = @env.get_env_vars()
551	  let secrets = [] + protected_secrets.unwrap_or([])
552	  if environment is Some(environment) {
553	    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
554	      secrets.push(secret)
555	    }
556	  }
557	  if tunnel_directory is Some(directory) &&
558	    diagnostic_workspace_environments.get(directory) is Some(environment) {
559	    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
560	      secrets.push(secret)
561	    }
562	  }
563	  if error_message is Some(message) {
564	    let message = diagnostic_text(
565	      message,
566	      environment=process_environment,
567	      protected_secrets=secrets,
568	    )
569	    set_field(event, "errorMessage", Json::string(message))
570	    set_field(
571	      event,
572	      "detailsTruncated",
573	      Json::boolean(
574	        details_truncated ||
575	        message == "[error details incomplete or truncated]" ||
576	        message.has_suffix("\n[error details incomplete or truncated]"),
577	      ),
578	    )
579	  }
580	  if tunnel_directory is Some(directory) {
581	    set_field(
582	      event,
583	      "tunnelDirectory",
584	      Json::string(
585	        diagnostic_text(
586	          directory,
587	          environment=process_environment,
588	          protected_secrets=secrets,
589	        ),
590	      ),
591	    )
592	  }
593	  for
594	    pair in [
595	      ("expectedWorkspaceUid", expected_workspace_uid),
596	      ("observedWorkspaceUid", observed_workspace_uid),
597	    ] {
598	    if pair.1 is Some(value) {
599	      set_field(
600	        event,
601	        pair.0,
602	        Json::string(
603	          diagnostic_text(
604	            value,
605	            environment=process_environment,
606	            protected_secrets=secrets,
607	          ),
608	        ),
609	      )
610	    }
611	  }
612	  let evidence_truncated : Ref[Bool] = { val: evidence_incomplete, }
613	  if source is Some(evidence) {
614	    let value = evidence.to_json()
615	    if value.stringify().length() <= 65536 {
616	      set_field(
617	        event,
618	        "source",
619	        diagnostic_json(
620	          value,
621	          process_environment,
622	          secrets,
623	          evidence_truncated,
624	          0,
625	          stable_activity=evidence_stable_activity,
626	        ),
627	      )
628	    } else {
629	      evidence_truncated.val = true
630	    }
631	  }
632	  if evidence is Some(value) {
633	    if value.stringify().length() <= 65536 {
634	      set_field(
635	        event,
636	        "evidence",
637	        diagnostic_json(
638	          value,
639	          process_environment,
640	          secrets,
641	          evidence_truncated,
642	          0,
643	          stable_activity=evidence_stable_activity,
644	          secret_states=stage == "server-environment",
645	          stable_operation=evidence_stable_operation,
646	        ),
647	      )
648	    } else {
649	      evidence_truncated.val = true
650	    }
651	  }
652	  if evidence_truncated.val {
653	    set_field(event, "evidenceTruncated", Json::boolean(true))
654	    set_field(event, "completeness", Json::string("partial"))
655	  }
656	  if details_truncated ||
657	    evidence_truncated.val ||
658	    (
659	      error_message is Some(message) &&
660	      message.contains("[error details incomplete or truncated]")
661	    ) {
662	    diagnostic_recording_health.run_partial = true
663	  }
664	  if run_completeness is Some(value) {
665	    set_field(event, "runCompleteness", Json::string(value))
666	  }
667	  if os_errno is Some(code) && code > 0 && code < 4096 {
668	    set_field(event, "osErrno", Json::number(code.to_double()))
669	  }
670	  if exit_code is Some(code) {
671	    set_field(event, "exitCode", Json::number(code.to_double()))
672	  }
673	  for pair in [("errorType", error_type), ("phase", phase)] {
674	    if pair.1 is Some(text) {
675	      set_field(event, pair.0, Json::string(text))
