 775	        set_field(
 776	          marker,
 777	          "missingThroughTime",
 778	          Json::string(@env.now().to_string()),
 779	        )
 780	        set_field(marker, "missingRange", Json::string("unknown"))
 781	        prefix = marker.stringify() +
 782	          "\n" +
 783	          diagnostic_retained_records(file, size)
 784	        replace = true
 785	      } else if size > 0L {
 786	        let tail = FixedArray::make(1, b'\x00')
 787	        guard file.read_at(tail, position=size - 1L) == 1 else {
 788	          raise AdapterError("Unable to inspect diagnostic record boundary")
 789	        }
 790	        if tail[0] != b'\n' {
 791	          let bytes = FixedArray::make(size.to_int(), b'\x00')
 792	          let read = file.read_at(bytes, position=0L)
 793	          let mut complete = read
 794	          while complete > 0 && bytes[complete - 1] != b'\n' {
 795	            complete -= 1
 796	          }
 797	          prefix = @utf8.decode_lossy(
 798	            bytes.unsafe_reinterpret_as_bytes()[:complete],
 799	          )
 800	          let marker = diagnostic_recording_event(
 801	            "degraded",
 802	            if read != size.to_int() {
 803	              "short_read"
 804	            } else {
 805	              "incomplete_record"
 806	            },
 807	          )
 808	          set_field(marker, "missingRange", Json::string("unknown"))
 809	          prefix += marker.stringify() + "\n"
 810	          replace = true
 811	        }
 812	      }
 813	    }
 814	    let recorded_drops = diagnostic_recording_health.dropped
 815	    let incident_serial = diagnostic_recording_health.incident_serial
 816	    if recorded_drops > 0 || diagnostic_recording_health.incident {
 817	      let marker = diagnostic_recording_event(
 818	        if recorded_drops > 0 {
 819	          "degraded"
 820	        } else {
 821	          "recovered"
 822	        },
 823	        diagnostic_recording_health.reason,
 824	      )
 825	      if recorded_drops > 0 {
 826	        set_field(
 827	          marker,
 828	          "droppedEvents",
 829	          Json::number(recorded_drops.to_double()),
 830	        )
 831	        set_field(
 832	          marker,
 833	          "missingFromTime",
 834	          Json::string(diagnostic_recording_health.first_dropped.to_string()),
 835	        )
 836	        set_field(
 837	          marker,
 838	          "missingThroughTime",
 839	          Json::string(diagnostic_recording_health.last_dropped.to_string()),
 840	        )
 841	      } else {
 842	        set_field(marker, "completeness", Json::string("complete"))
 843	      }
 844	      if diagnostic_recording_health.phase != "" {
 845	        set_field(
 846	          marker,
 847	          "phase",
 848	          Json::string(diagnostic_recording_health.phase),
 849	        )
 850	      }
 851	      if diagnostic_recording_health.os_errno is Some(code) {
 852	        set_field(marker, "osErrno", Json::number(code.to_double()))
 853	      }
 854	      prefix += marker.stringify() + "\n"
 855	    }
 856	    let count = diagnostic_pending.length()
 857	    diagnostic_pending_inflight.val = count
 858	    defer {
 859	      diagnostic_pending_inflight.val = 0
 860	    }
 861	    let records = @buffer.Buffer(size_hint=4096)
 862	    for index in 0..<count {
 863	      records.write_string_utf8(
 864	        diagnostic_pending[index].event.stringify() + "\n",
 865	      )
 866	    }
 867	    let content = prefix + @utf8.decode_lossy(records.to_bytes())
 868	    failure_phase = if replace { "replace" } else { "append" }
 869	    if replace {
 870	      let temporary = path + ".rotate." + proxy_pid().to_string()
 871	      defer (@fs.remove(temporary) catch { _ => () })
 872	      @fs.write_file(temporary, content, permission=0o600)
 873	      @fs.rename(temporary, path, replace=true)
 874	    } else {
 875	      @fs.write_file(
 876	        path,
 877	        content,
 878	        permission=0o600,
 879	        append=true,
 880	        create_mode=OpenOrCreate,
 881	      )
 882	    }
 883	    for _ in 0..<count {
 884	      ignore(diagnostic_pending.remove(0))
 885	    }
 886	    diagnostic_previous_losses.clear()
 887	    diagnostic_recording_health.dropped -= recorded_drops
 888	    if diagnostic_recording_health.incident_serial == incident_serial {
 889	      diagnostic_recording_health.incident = false
 890	      health_changed = true
 891	    }
 892	  }) catch {
 893	    error =>
 894	      if !@async.is_being_cancelled() {
 895	        diagnostic_recording_warning(
 896	          if error is @async.TimeoutError {
 897	            "store_timeout"
 898	          } else {
 899	            "store_unavailable"
 900	          },
 901	          phase=failure_phase,
 902	          os_errno?=match error {
 903	            @os_error.OSError(code, ..) => Some(code)
 904	            _ => None
 905	          },
 906	        )
 907	      }
 908	  }
 909	  if health_changed {
 910	    publish_diagnostic_health()
 911	    if diagnostic_recording_health.incident {
 912	      publish_diagnostic_health()
 913	    }
 914	  }
 915	}
