 967	///|
 968	fn diagnostic_error(
 969	  error : Error,
 970	  environment? : Map[String, String],
 971	) -> String {
 972	  let (message, omitted) = match error {
 973	    AdapterError(detail) => (detail, false)
 974	    InvalidConfig(detail) => (detail, false)
 975	    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
 976	    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
 977	    @json.InvalidNumber(position, _) =>
 978	      (
 979	        "Invalid JSON number at line \{position.line}, column \{position.column}; value omitted",
 980	        true,
 981	      )
 982	    _ => (error.to_string(), false)
 983	  }
 984	  diagnostic_text(message, environment?, omitted~)
 985	}
