1086	priv struct DiagnosticProtectedValues {

  1	///|
  2	fn credential_field(name : String) -> Bool {
  3	  let chars = name.trim_start(chars="-").iter().to_array()
  4	  let normalized = @buffer.Buffer(size_hint=name.length())
  5	  for i in 0..<chars.length() {
  6	    let c = chars[i]
  7	    if i > 0 &&
  8	      c >= 'A' &&
  9	      c <= 'Z' &&
 10	      (
 11	        (chars[i - 1] >= 'a' && chars[i - 1] <= 'z') ||
 12	        (chars[i - 1] >= '0' && chars[i - 1] <= '9')
 13	      ) {
 14	      normalized.write_char_utf8('_')
 15	    }
 16	    normalized.write_char_utf8(if c == '-' { '_' } else { c })
 17	  }
 18	  let name = @utf8.decode_lossy(normalized.to_bytes()).to_lower()
 19	  [
 20	    "auth", "authorization", "proxy_authorization", "cookie", "set_cookie", "password",
 21	    "passwd", "token", "access_token", "accesstoken", "refresh_token", "refreshtoken",
 22	    "id_token", "api_key", "apikey", "x_api_key", "credential", "credentials", "secret",
 23	    "client_secret", "clientsecret", "private_key", "privatekey", "aws_secret_access_key",
 24	    "azure_storage_key", "docker_auth_config", "signature", "sig", "x_amz_signature",
 25	    "x_amz_security_token", "x_goog_signature",
 26	  ].contains(name) ||
 27	  name
 28	  .split("_")
 29	  .iter()
 30	  .any(part => {
 31	    [
 32	      "auth", "authorization", "cookie", "password", "passwd", "passphrase", "token",
 33	      "secret", "apikey", "credential", "credentials", "signature", "pairingcode",
 34	      "privatekey", "clientsecret", "accesstoken", "refreshtoken", "proxyauthorization",
 35	      "setcookie",
 36	    ].contains(part.to_owned())
 37	  }) ||
 38	  name.contains("_api_key_") ||
 39	  name.has_prefix("api_key_") ||
 40	  name.has_suffix("_api_key") ||
 41	  name.contains("_private_key_") ||
 42	  name.has_prefix("private_key_") ||
 43	  name.has_suffix("_private_key") ||
 44	  name == "pairing_code" ||
 45	  name.contains("_pairing_code_") ||
 46	  name.has_prefix("pairing_code_") ||
 47	  name.has_suffix("_pairing_code")
 48	}
