 16	///|
 17	priv struct ProgressSink {
 18	  lock : @async.Mutex
 19	  mut available : Bool
 20	}
 21	
 22	///|
 23	let progress_sink : ProgressSink = {
 24	  lock: @async.Mutex::Mutex(),
 25	  available: true,
 26	}
 27	
 28	///|
 29	async fn progress_write(message : String) -> Unit {
 30	  progress_sink.lock.acquire()
 31	  defer progress_sink.lock.release()
 32	  if !progress_sink.available {
 33	    return
 34	  }
 35	  @stdio.stderr.write(message) catch {
 36	    _ => {
 37	      progress_sink.available = false
 38	      save_diagnostic("progress-output", "failed", error_type="progress_io")
 39	    }
 40	  }
 41	}
