234	fn Progress::remember(
235	  self : Progress,
236	  message : String,
237	  warning~ : Bool,
238	) -> Unit {
239	  let lines = if warning { self.failures } else { self.recent }
240	  if lines.last() == Some(message) {
241	    return
242	  }
243	  if lines.length() == 8 {
244	    ignore(lines.remove(0))
245	    self.details_truncated = true
246	  }
247	  lines.push(message)
248	}
