252	  let lines = self.failures +
253	    self.recent.filter(line => !self.failures.contains(line))
254	  let detail = if lines.is_empty() {
255	    "no readable error message from subprocess"
256	  } else {
257	    lines.join("\n")
258	  }
259	  detail +
260	  (if self.details_truncated {
261	    "\n[error details incomplete or truncated]"
262	  } else {
263	    ""
