267	///|
268	async fn Progress::status(self : Progress, event : Json) -> Unit {
269	  guard field(event, "phase") is Some(Json::String(phase)) &&
270	    phase_label(phase) is Some(label) &&
271	    field(event, "state") is Some(Json::String(state)) &&
272	    ["started", "succeeded", "failed", "skipped"].contains(state) else {
273	    return
274	  }
275	  if self.phase_count < 128 {
276	    self.phase_count += 1
277	    save_diagnostic(
278	      self.stage,
279	      state,
280	      phase~,
281	      error_type?=if state == "failed" { Some("backend_phase") } else { None },
282	      evidence?=self.context,
283	      evidence_stable_operation=true,
284	      protected_secrets=self.secrets,
285	      recording=self.recording,
286	    )
287	  } else if self.phase_count == 128 {
288	    self.phase_count += 1
289	    save_diagnostic(
290	      self.stage,
291	      "diagnostics-truncated",
292	      error_type="phase_limit",
293	      evidence?=self.context,
294	      evidence_stable_operation=true,
295	      protected_secrets=self.secrets,
296	      recording=self.recording,
297	    )
298	  }
299	  let key = ["pipeline", "operationId", "phase", "step"]
300	    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
301	    .join(":")
302	  if state == "started" {
303	    if self.operations.length() >= 256 {
304	      self.operations.clear()
305	    }
306	    self.operations.set(key, @env.now())
307	    progress_message(label + ": running…")
308	  } else {
309	    let duration = match field(event, "durationMs") {
310	      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
311	        Some(seconds(value.to_uint64()))
312	      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
313	    }
314	    self.operations.remove(key)
315	    let timing = duration.map(value => value + ", ").unwrap_or("") +
316	      "elapsed " +
317	      seconds(@env.now() - progress_started)
318	    progress_message(
319	      label +
320	      ": " +
321	      (if state == "succeeded" { "done" } else { state }) +
322	      " (" +
323	      timing +
324	      ")",
325	    )
326	  }
327	}
