329	///|
330	fn classic_build_step(text : String) -> Bool {
331	  guard text.has_prefix("Step ") &&
332	    text[5:].split_once("/") is Some((step, rest)) &&
333	    rest.split_once(" ") is Some((total, detail)) else {
334	    return false
335	  }
336	  step.length() > 0 &&
337	  total.length() > 0 &&
338	  step.iter().all(c => c >= '0' && c <= '9') &&
339	  total.iter().all(c => c >= '0' && c <= '9') &&
340	  detail.trim().has_prefix(":")
341	}
