535	///|
536	async fn Progress::read_output(
537	  self : Progress,
538	  reader : @process.ReadFromProcess,
539	  capture~ : Bool,
540	  statuses~ : Bool = false,
541	  messages~ : Bool = false,
542	  raw_messages~ : Bool = false,
543	) -> String {
544	  let output = @buffer.Buffer(size_hint=4096)
545	  let pending = @buffer.Buffer(size_hint=4096)
546	  let mut oversized = false
547	  let mut tail = ""
548	  while reader.read_some(max_len=4096) is Some(chunk) {
549	    if capture {
550	      output.write_bytes(chunk)
551	    } else {
552	      tail += @utf8.decode_lossy(chunk)
553	      if tail.length() > 8192 {
554	        tail = tail[tail.length() - 8192:].to_owned()
555	      }
556	    }
557	    for byte in chunk {
558	      if byte == b'\n' || byte == b'\r' {
559	        if !oversized && pending.length() > 0 {
560	          let line = @utf8.decode(pending.to_bytes()) catch {
561	            _ => {
562	              self.details_truncated = true
563	              ""
564	            }
565	          }
566	          if raw_messages {
567	            self.message(line, debug=false, warning=true, emit=false)
568	          } else if capture {
569	            self.line(line, statuses~, messages~)
570	          } else {
571	            self.stderr_line(line, statuses~, messages~)
572	          }
573	        }
574	        pending.reset()
575	        oversized = false
576	      } else if !oversized {
577	        if pending.length() == 65536 {
578	          pending.reset()
579	          oversized = true
580	          self.details_truncated = true
581	        } else {
582	          pending.write_byte(byte)
583	        }
584	      }
585	    }
586	  }
587	  if !oversized && pending.length() > 0 {
588	    let line = @utf8.decode(pending.to_bytes()) catch {
589	      _ => {
590	        self.details_truncated = true
591	        ""
592	      }
593	    }
594	    let masked = diagnostic_partial_secret(line, self.secrets)
595	    if masked != line {
596	      self.details_truncated = true
597	    }
598	    if raw_messages {
599	      self.message(masked, debug=false, warning=true, emit=false)
600	    } else if capture {
601	      self.line(masked, statuses~, messages~)
602	    } else {
603	      self.stderr_line(masked, statuses~, messages~)
604	    }
605	  }
606	  if capture {
607	    @utf8.decode(output.to_bytes())
608	  } else {
609	    tail
610	  }
611	}

