 34	///|
 35	async fn command_result(
 36	  program : String,
 37	  args : Array[String],
 38	  stage : String,
 39	  environment? : Map[String, String],
 40	  cwd? : StringView,
 41	  target? : String,
 42	  recording_override? : Bool,
 43	  protected_secrets? : Array[String],
 44	  protection_incomplete~ : Bool = false,
 45	) -> (Int32, String, String) {
 46	  let recording = recording_override.unwrap_or(
 47	    environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
 48	    Some("0"),
 49	  )
 50	  let context : Json? = if recording {
 51	    diagnostic_operation_counter.val += 1
 52	    let value : Json = {
 53	      "operationId": recording_run_id +
 54	      ":" +
 55	      diagnostic_operation_counter.val.to_string(),
 56	    }
 57	    if target is Some(id) {
 58	      set_field(value, "workspaceId", Json::string(id))
 59	    }
 60	    Some(value)
 61	  } else {
 62	    None
 63	  }
 64	  save_diagnostic(
 65	    stage,
 66	    "started",
 67	    evidence?=context,
 68	    evidence_stable_operation=true,
 69	    environment?,
 70	    protected_secrets?,
 71	    recording~,
 72	  )
 73	  let started = @env.now()
 74	  let progress = Progress::new(
 75	    stage,
 76	    environment?,
 77	    context?,
 78	    recording_override=recording,
 79	    protected_secrets?,
 80	    protection_incomplete~,
 81	  )
 82	  let label = target.map(value => value + ": " + stage).unwrap_or(stage)
 83	  progress_message(label + ": running…")
 84	  let mut failure_kind = "process_api"
 85	  let mut failure_errno = None
 86	  let mut failure_phase = None
 87	  let (status, output, errors) = {
 88	    errdefer {
 89	      save_diagnostic(
 90	        stage,
 91	        if @async.is_being_cancelled() {
 92	          "cancelled"
 93	        } else {
 94	          "process-error"
 95	        },
 96	        error_type=failure_kind,
 97	        os_errno?=failure_errno,
 98	        phase?=failure_phase,
 99	        error_message=progress.failure_detail(),
100	        details_truncated=progress.details_truncated,
101	        evidence?=context,
102	        evidence_stable_operation=true,
103	        environment?,
104	        protected_secrets?,
105	        recording~,
106	      )
107	      progress_message(label + ": failed (" + progress_timing(started) + ")")
108	    }
109	    try {
110	      let (out, stdout) = @process.read_from_process()
111	      defer out.close()
112	      let (err, stderr) = @process.read_from_process()
113	      defer err.close()
114	      @async.with_task_group(async fn(group) {
115	        let child = @process.spawn(
116	          group,
117	          program,
118	          args,
119	          extra_env?=environment,
120	          inherit_env=environment is None,
121	          cwd?,
122	          stdout~,
123	          stderr~,
124	        )
125	        let output = group.spawn(async fn() {
126	          progress.read_output(
127	            out,
128	            capture=true,
129	            statuses=devsy_progress_stage(stage),
130	            messages=stage == "orca-install" || stage == "checkout-workspace",
131	          )
132	        })
133	        let errors = group.spawn(async fn() {
134	          progress.read_output(
135	            err,
136	            capture=false,
137	            messages=devsy_progress_stage(stage) ||
138	              stage == "orca-install" ||
139	              stage == "checkout-workspace",
140	          )
141	        })
142	        (child.wait(), output.wait(), errors.wait())
143	      })
144	    } catch {
145	      @os_error.OSError(code, ..) as error => {
146	        failure_kind = "process_os"
147	        failure_errno = Some(code)
148	        let message = if protection_incomplete {
149	          progress.details_truncated = true
150	          "subprocess OS error \{code}; workspace protection values unavailable"
151	        } else {
152	          progress
153	          .safe_message(program + ": " + error.to_string())
154	          .unwrap_or("subprocess OS error \{code}")
155	        }
156	        progress.remember(message, warning=true)
157	        raise AdapterError(
158	          "\{stage} failed (OS error \{code}); diagnostic run \{recording_run_id}:\n" +
159	          message,
160	        )
161	      }
162	      @utf8.Malformed(_) => {
163	        failure_kind = "process_utf8"
164	        failure_phase = Some("read")
165	        progress.remember("subprocess output is not valid UTF-8", warning=true)
166	        raise AdapterError(
167	          "\{stage} failed: subprocess output is not valid UTF-8; diagnostic run \{recording_run_id}",
168	        )
169	      }
170	      error => {
171	        if !@async.is_being_cancelled() {
172	          let detail = if protection_incomplete {
173	            progress.details_truncated = true
174	            "error detail unavailable because workspace protection values could not be read"
175	          } else {
176	            diagnostic_text(
177	              diagnostic_error(error, environment?),
178	              environment?,
179	              protected_secrets=progress.secrets,
180	            )
181	          }
182	          for line in detail.split("\n") {
183	            progress.remember(line.to_owned(), warning=true)
184	          }
185	        }
186	        raise error
187	      }
188	    }
189	  }
190	  progress_message(
191	    label +
192	    ": " +
193	    (if status == 0 { "done" } else { "failed (exit \{status})" }) +
194	    " (" +
195	    progress_timing(started) +
196	    ")",
197	  )
198	  save_diagnostic(
199	    stage,
200	    if status == 0 {
201	      "success"
202	    } else {
203	      "exit-error"
204	    },
205	    exit_code=status,
206	    duration_ms=(@env.now() - started).to_double(),
207	    error_message?=if status == 0 {
208	      None
209	    } else {
210	      Some(progress.failure_detail())
211	    },
212	    details_truncated=progress.details_truncated,
213	    evidence?=context,
214	    evidence_stable_operation=true,
215	    environment?,
216	    protected_secrets?,
217	    error_type?=if status == 0 || !recording {
218	      None
219	    } else {
220	      Some(process_error_type(output + "\n" + errors))
221	    },
222	    recording~,
223	  )
224	  (status, output, progress.failure_detail())
225	}
