274	///|
275	fn workspace_environment(state : Json) -> Map[String, String] {
276	  let environment = match field(state, "executionEnvironment") {
277	    Some(Json::Object(values)) => {
278	      let result : Map[String, String] = Map([])
279	      for (name, value) in values {
280	        if value is Json::String(value) {
281	          result.set(name, value)
282	        }
283	      }
284	      result
285	    }
286	    _ => @env.get_env_vars()
287	  }
288	  for name in location_variables {
289	    match field(field(state, "devsyEnv").unwrap_or(Json::null()), name) {
290	      Some(Json::String(value)) => environment.set(name, value)
291	      _ => environment.remove(name)
292	    }
293	  }
294	  environment
295	}
