340	///|
341	async fn devsy_result(
342	  state : Json,
343	  args : Array[String],
344	  stage : String,
345	) -> (Int32, String, String) {
346	  let environment = workspace_environment(state)
347	  let protected_values = workspace_output_secrets(state)
348	  if protected_values is None {
349	    suppress_workspace_recording(state)
350	  }
351	  let invocation = saved_command(state)
352	  let logging = if devsy_progress_stage(stage) {
353	    ["--log-level", "debug", "--log-output", "json"]
354	  } else {
355	    []
356	  }
357	  let result = command_result(
358	    workspace_program(state, invocation[0]),
359	    invocation[1:].to_owned() + devsy_args(state) + logging + args,
360	    stage,
361	    environment~,
362	    recording_override=state_recording(state),
363	    protected_secrets?=protected_values,
364	    protection_incomplete=protected_values is None,
365	    cwd?=workspace_directory(state).map(path => path[:]),
366	    target?=field(state, "workspaceId").map(value => {
367	      if value is Json::String(name) {
368	        name
369	      } else {
370	        ""
371	      }
372	    }),
373	  )
374	  result
375	}
376	
377	///|
378	async fn devsy(state : Json, args : Array[String], stage : String) -> String {
379	  let (status, output, detail) = devsy_result(state, args, stage)
380	  guard status == 0 else {
381	    raise AdapterError(command_failure(stage, status, detail))
382	  }
383	  output
384	}
