1302	        self.output.write_bytes(chunk[:count])
1303	      }
1304	      if count < chunk.length() {
1305	        self.truncated = true
1306	      }
1307	    }
1308	  } catch {
1309	    error =>
1310	      if @async.is_being_cancelled() {
1311	        raise error
1312	      } else {
1313	        self.truncated = true
1314	      }
1315	  }
1316	  self.finished = true
1317	}
