 ///|
 pub async fn bulk(mode : String, args : Array[String]) -> Unit {
+  defer @async.protect_from_cancel(async fn() { finish_diagnostic_recording() })
+  let mut failure_recorded = false
+  let recording_allowed : Ref[Bool] = {
+    val: @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
+  }
+  errdefer (if !failure_recorded && @async.is_being_cancelled() {
+    @async.protect_from_cancel(async fn() {
+      save_diagnostic(
+        "bulk",
+        "cancelled",
+        error_type="cancelled",
+        recording=recording_allowed.val,
+      )
+    })
+  })
+  let mut failures = 0
+  let error = try {
+    failures = bulk_inner(mode, args, recording_allowed)
+    None
+  } catch {
+    error => Some(error)
+  }
+  if error is Some(error) {
+    save_command_failure("bulk", error, recording=recording_allowed.val)
+    failure_recorded = true
+    raise error
+  }
+  guard failures == 0 else {
+    raise AdapterError("Some workspace operations failed")
+  }
+}
