344	async fn Progress::message(
345	  self : Progress,
346	  text : String,
347	  debug~ : Bool,
348	  warning~ : Bool,
349	  emit~ : Bool = true,
350	) -> Unit {
351	  if self.protection_incomplete {
352	    self.details_truncated = true
353	    self.remember(
354	      "error detail unavailable because workspace protection values could not be read",
355	      warning=true,
356	    )
357	    return
358	  }
359	  for line in text.split("\n") {
360	    let text = line.trim().to_owned()
361	    if text == "" {
362	      continue
363	    }
364	    guard self.safe_message(text) is Some(safe) else {
365	      self.details_truncated = true
366	      continue
367	    }
368	    if !debug || warning {
369	      self.remember(safe, warning~)
370	    }
371	    if !emit {
372	      continue
373	    }
374	    if safe.has_prefix("#") {
375	      guard safe.split_once(" ") is Some((id, rest)) &&
376	        id.length() > 1 &&
377	        id[1:].iter().all(c => c >= '0' && c <= '9') else {
378	        continue
379	      }
380	      let detail = rest.trim().to_owned()
381	      guard detail.has_prefix("[") ||
382	        detail.has_prefix("DONE") ||
383	        detail.has_prefix("ERROR") ||
384	        detail.has_prefix("CACHED") else {
385	        continue
386	      }
387	      if detail.has_prefix("ERROR") && debug && !warning {
388	        self.remember(safe, warning=true)
389	      }
390	      if self.builds.get(id.to_owned()) == Some(detail) {
391	        continue
392	      }
393	      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
394	        self.builds.set(id.to_owned(), detail)
395	      }
396	      progress_message("Build " + id.to_owned() + ": " + detail)
397	    } else if classic_build_step(safe) {
398	      // Classic RUN output has no prefix. Only its own completion marker
399	      // ends this mode; phase events on another pipe can arrive ahead of it.
400	      self.classic_build = true
401	      progress_message("Build " + safe)
402	    } else if safe.has_prefix("Successfully built ") ||
403	      safe.has_prefix("Successfully tagged ") {
404	      self.classic_build = false
405	      progress_message("Build: " + safe)
406	    } else if self.classic_build && !warning {
407	      continue
408	    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
409	      progress_message(self.stage + ": " + safe)
410	    } else if !debug && safe.has_prefix("[credential") {
411	      progress_message(self.stage + ": " + safe)
412	    }
413	  }
414	}
